import { useEffect, useState } from 'react';

/**
 * Says a moment to a screen reader once, politely: the region is on the
 * page empty and the words arrive a frame later, which is what makes a
 * live region speak. The visible moment is not read twice because it is
 * not a live region itself.
 */
export function Announce({ text }: { text: string }): React.JSX.Element {
  const [said, setSaid] = useState('');
  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      setSaid(text);
    });
    return () => {
      cancelAnimationFrame(frame);
    };
  }, [text]);
  return (
    <p className="sr-only" role="status" aria-live="polite">
      {said}
    </p>
  );
}
